INSERT INTO dispute_routes (issue_type,payment_method,provider_key,level,organization,route_type,channel,destination,official_url,prerequisite,required_documents,response_expectation_hours,active,source_url) SELECT 'consumer_issue',NULL,'bank_'||b.bank_key,1,b.display_name,'BANK_GRIEVANCE','PORTAL_OR_CALL',b.display_name||' complaint / grievance redressal',b.complaint_url,'[{"condition":"payer_bank_identified","required":true}]'::jsonb,'["payment proof","transaction reference","bank debit proof","case summary"]'::jsonb,COALESCE(b.response_expectation_days,30)*24,true,b.source_url FROM bank_directory b WHERE b.active=true AND NOT EXISTS (SELECT 1 FROM dispute_routes r WHERE r.provider_key='bank_'||b.bank_key AND r.level=1 AND r.issue_type='consumer_issue');